def write_captions(path):
    with open(path, "w") as f:
        f.write("# Draft captions for Paper B1 figures\n\nGenerated by build_figures.py from VISUALS_PLAN.md drafts, edited to match what is drawn. "
                "Each caption is followed by the checks made against the picture and the plotted data (and any change from the plan draft). Figures are in this folder as .png (300 dpi), .pdf and .svg.\n\n")
        for name, title, text, chk in CAP:
            f.write(f"## {name}\n\n**{title}** {text}\n\n*Check against the drawing:* {chk}\n\n")
